              "flow": [
                "issue_snapshot",
                {
                  "if": {
                    "condition": {
                      "path": "/0/data/status",
                      "equals": "review"
                    },
                    "then": [
                      "diagnose",
                      {
                        "if": {
                          "condition": {
                            "path": "/0/data/status",
                            "equals": "needs_information"
                          },
                          "then": [
                            "ask_information",
                            {
                              "if": {
                                "condition": {
                                  "path": "/0/data/status",
                                  "equals": "needs_information"
                                },
                                "then": [
                                  "wait_for_issue_update"
                                ],
                                "else": []
                              }
                            }
                          ],
                          "else": [
                            {
                              "if": {
                                "condition": {
                                  "path": "/0/data/status",
                                  "equals": "ready"
                                },
                                "then": [
                                  "check_issue_open"
                                ],
                                "else": []
                              }
                            }
                          ]
                        }
                      }
                    ],
                    "else": []
                  }
                }
              ],
              "while": {
                "path": "/0/data/status",
                "equals": "updated"
              }
            }
          }
        ],
        "else": [
          {
            "loop": {
              "flow": [
                "issue_snapshot",
                {
                  "if": {
                    "condition": {
                      "path": "/0/data/status",
                      "equals": "review"
                    },
                    "then": [
                      "readiness",
                      {
                        "if": {
                          "condition": {
                            "path": "/0/data/status",
                            "equals": "needs_information"
                          },
                          "then": [
                            "ask_information",
                            {
                              "if": {
                                "condition": {
                                  "path": "/0/data/status",
                                  "equals": "needs_information"
                                },
                                "then": [
                                  "wait_for_issue_update"
                                ],
                                "else": []
                              }
                            }
                          ],
                          "else": [
                            {
                              "if": {
                                "condition": {
                                  "path": "/0/data/status",
                                  "equals": "ready"
                                },
                                "then": [
                                  "check_issue_open"
                                ],
                                "else": []
                              }
                            }
                          ]
                        }
                      }
                    ],
                    "else": []
                  }
                }
              ],
              "while": {
                "path": "/0/data/status",
                "equals": "updated"
              }
            }
          }
        ]
      }
    },
    {
      "if": {
        "condition": {
          "path": "/0/data/status",
          "equals": "ready"
        },
        "then": [
          "implement",
          "publish",
          {
            "loop": {
              "flow": [
                "review_snapshot",
                {
                  "if": {
                    "condition": {
                      "path": "/0/data/status",
                      "equals": "review"
                    },
                    "then": [
                      "review"
                    ],
                    "else": []
                  }
                },
                {
                  "loop": {
                    "flow": [
                      {
                        "if": {
                          "condition": {
                            "path": "/0/data/status",
                            "equals": "needs_fixes"
                          },
                          "then": [
                            "fix",
                            "publish",
                            "review_snapshot",
                            {
                              "if": {
                                "condition": {
                                  "path": "/0/data/status",
                                  "equals": "review"
                                },
                                "then": [
                                  "review"
                                ],
                                "else": []
                              }
                            }
                          ],
                          "else": [
                            {
                              "if": {
                                "condition": {
                                  "path": "/0/data/status",
                                  "equals": "needs_confirmation"
                                },
                                "then": [
                                  "request_confirmation",
                                  {
                                    "if": {
                                      "condition": {
                                        "path": "/0/data/status",
                                        "equals": "needs_confirmation"
                                      },
                                      "then": [
                                        "wait_for_confirmation"
                                      ],
                                      "else": []
                                    }
                                  },
                                  {
                                    "if": {
                                      "condition": {
                                        "path": "/0/data/status",
                                        "equals": "updated"
                                      },
                                      "then": [
                                        "review"
                                      ],
                                      "else": []
                                    }
                                  }
                                ],
                                "else": []
                              }
                            }
                          ]
                        }
                      }
                    ],
                    "while": {
                      "path": "/0/data/retry_review",
                      "equals": true
                    }
                  }
                },
                {
                  "if": {
                    "condition": {
                      "path": "/0/data/approved",
                      "equals": true
                    },
                    "then": [
                      "merge"
                    ],
                    "else": [
                      "review_closed"
                    ]
                  }
                }
              ],
              "while": {
                "path": "/0/data/retry",
                "equals": true
              }
            }
          },
          "close_issue"
        ],
        "else": []
      }
    }
